function stripEnclosingInstructionQuotes(value) {
  const text = cleanText(value);
  const match = text.match(/^(?:["“])([\s\S]*?)(?:["”])([.!?]?)$/);
  return match ? `${match[1]}${match[2]}`.trim() : text;
}

